# owner: platform
import unittest

from hourglass.timesheet import timesheet_rows
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError


def shift(worker, day, start, end):
    return Shift(worker, day, Span(start, end))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        rows = timesheet_rows([
            shift("Ana", "mon", 540, 600),
            shift("Bo", "mon", 540, 780),
            shift("Ana", "tue", 540, 570),
        ])
        self.assertEqual(rows, [
            "Bo: 1 shifts, 4.0 h",
            "Ana: 2 shifts, 1.5 h",
        ])

    def test_empty(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([])

    def test_blank_worker(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([shift(" ", "mon", 540, 600)])
